<html lang="pt">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?= $expedition ? 'Editar expediente' : 'Novo expediente' ?> | Gestão de Expedientes</title><link rel="stylesheet" href="assets/css/style.css"></head>
<body class="app-page dashboard-layout">
<?php $activePage = 'expedientes'; $pageTitle = 'Expediente'; require __DIR__ . '/partials/app-header.php'; ?>
<main class="content-shell narrow-shell"><p class="section-kicker">Gestão documental</p><h1><?= $expedition ? 'Editar expediente' : 'Novo expediente' ?></h1><p class="muted">Preencha os dados principais do documento administrativo.</p><?php if ($message): ?><div class="flash <?= htmlspecialchars($message['type'], ENT_QUOTES, 'UTF-8') ?>" role="alert"><?= htmlspecialchars($message['message'], ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
<form class="user-form" method="post" action="expediente-save.php"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(getCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><?php if ($expedition): ?><input type="hidden" name="id" value="<?= (int) $expedition['id'] ?>"><?php endif; ?><label for="reference_code">Número/código</label><input id="reference_code" name="reference_code" required maxlength="50" value="<?= htmlspecialchars($expedition['reference_code'] ?? '', ENT_QUOTES, 'UTF-8') ?>"><label for="subject">Assunto</label><input id="subject" name="subject" required maxlength="255" value="<?= htmlspecialchars($expedition['subject'] ?? '', ENT_QUOTES, 'UTF-8') ?>"><label for="description">Descrição</label><textarea id="description" name="description" rows="5"><?= htmlspecialchars($expedition['description'] ?? '', ENT_QUOTES, 'UTF-8') ?></textarea><label for="document_type">Tipo de documento</label><input id="document_type" name="document_type" maxlength="100" value="<?= htmlspecialchars($expedition['document_type'] ?? '', ENT_QUOTES, 'UTF-8') ?>"><label for="origin">Remetente/origem</label><input id="origin" name="origin" required maxlength="150" value="<?= htmlspecialchars($expedition['origin'] ?? '', ENT_QUOTES, 'UTF-8') ?>"><label for="destination">Destinatário/setor</label><input id="destination" name="destination" required maxlength="150" value="<?= htmlspecialchars($expedition['destination'] ?? '', ENT_QUOTES, 'UTF-8') ?>"><label for="received_at">Data de entrada</label><input id="received_at" name="received_at" type="datetime-local" required value="<?= $expedition ? date('Y-m-d\TH:i', strtotime($expedition['received_at'])) : date('Y-m-d\TH:i') ?>"><label for="priority">Prioridade</label><select id="priority" name="priority" required><?php foreach (['low' => 'Baixa', 'normal' => 'Normal', 'high' => 'Alta', 'urgent' => 'Urgente'] as $key => $label): ?><option value="<?= $key ?>" <?= ($expedition['priority'] ?? 'normal') === $key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select><label for="status">Estado</label><select id="status" name="status" required><?php foreach ($statuses as $key => $label): ?><option value="<?= htmlspecialchars($key, ENT_QUOTES, 'UTF-8') ?>" <?= ($expedition['status'] ?? 'received') === $key ? 'selected' : '' ?>><?= htmlspecialchars($label, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><button class="form-submit" type="submit"><?= $expedition ? 'Guardar alterações' : 'Registar expediente' ?></button></form></main></body></html>